__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"TEAM_MEMBERS",{enumerable:!0,get:function(){return s}});var n=r(d[0]);const s=[{name:{en:'Moses Fang',zh:'\u65b9\u821f','zh-cn':'\u65b9\u821f',es:'Moses Fang'},roleKey:'seniorPastor',imageUrl:n.PASTOR_IMAGE_URL,description:{en:'Originally from Shenyang, China, Pastor Moses Fang responded to God\u2019s call to ministry at the age of sixteen. He began serving in rural areas of China, where he planted churches, led Bible studies, preached, and engaged in pastoral ministry. Over the years, he served as a minister in several different regions.\n\nAfter coming to the United States, he served as the pastor of the Boston Chinese Seventh-day Adventist Church. He later graduated from Andrews University with a Master of Divinity (MDiv) degree. Since 2022, he has served as the pastor of the New York Chinese Seventh-day Adventist Church, where he continues his ministry in pastoral care and evangelism.',zh:'\u4f86\u81ea\u4e2d\u570b\u700b\u967d\uff0c\u81ea16\u6b72\u8499\u4e3b\u547c\u53ec\uff0c\u958b\u59cb\u53c3\u8207\u50b3\u9053\u4e8b\u5de5\uff0c\u5728\u4e2d\u570b\u8fb2\u6751\u5730\u5340\u5efa\u7acb\u6559\u6703\u3001\u5e36\u9818\u67e5\u7d93\u4e26\u5f9e\u4e8b\u8b1b\u9053\u8207\u7267\u990a\u5de5\u4f5c\uff0c\u66fe\u5148\u5f8c\u5728\u591a\u500b\u5730\u5340\u64d4\u4efb\u50b3\u9053\u4eba\u3002\u4f86\u7f8e\u5f8c\uff0c\u66fe\u64d4\u4efb\u6ce2\u58eb\u9813\u83ef\u4eba\u57fa\u7763\u5fa9\u81e8\u5b89\u606f\u65e5\u6703\u5802\u4e3b\u4efb\u3002\u5f8c\u7562\u696d\u65bc\u7f8e\u570b\u5b89\u5f97\u70c8\u5927\u5b78\uff08Andrews University\uff09\uff0c\u7372\u9053\u5b78\u78a9\u58eb\uff08Master of Divinity, MDiv\uff09\u5b78\u4f4d\u3002\u7562\u696d\u5f8c\uff0c\u81ea2022\u5e74\u8d77\u64d4\u4efb\u7d10\u7d04\u83ef\u4eba\u57fa\u7763\u5fa9\u81e8\u5b89\u606f\u65e5\u6703\u5802\u4e3b\u4efb\uff0c\u5f9e\u4e8b\u6559\u6703\u7267\u990a\u8207\u50b3\u9053\u4e8b\u5de5\u3002','zh-cn':'\u6765\u81ea\u4e2d\u56fd\u6c88\u9633\uff0c\u81ea16\u5c81\u8499\u4e3b\u547c\u53ec\uff0c\u5f00\u59cb\u53c2\u4e0e\u4f20\u9053\u4e8b\u5de5\uff0c\u5728\u4e2d\u56fd\u519c\u6751\u5730\u533a\u5efa\u7acb\u6559\u4f1a\u3001\u5e26\u9886\u67e5\u7ecf\u5e76\u4ece\u4e8b\u8bb2\u9053\u4e0e\u7267\u517b\u5de5\u4f5c\uff0c\u66fe\u5148\u540e\u5728\u591a\u4e2a\u5730\u533a\u62c5\u4efb\u4f20\u9053\u4eba\u3002\u6765\u7f8e\u540e\uff0c\u66fe\u62c5\u4efb\u6ce2\u58eb\u987f\u534e\u4eba\u57fa\u7763\u590d\u4e34\u5b89\u606f\u65e5\u4f1a\u5802\u4e3b\u4efb\u3002\u540e\u6bd5\u4e1a\u4e8e\u7f8e\u56fd\u5b89\u5f97\u70c8\u5927\u5b66\uff08Andrews University\uff09\uff0c\u83b7\u9053\u5b66\u7855\u58eb\uff08Master of Divinity, MDiv\uff09\u5b66\u4f4d\u3002\u6bd5\u4e1a\u540e\uff0c\u81ea2022\u5e74\u8d77\u62c5\u4efb\u7ebd\u7ea6\u534e\u4eba\u57fa\u7763\u590d\u4e34\u5b89\u606f\u65e5\u4f1a\u5802\u4e3b\u4efb\uff0c\u4ece\u4e8b\u6559\u4f1a\u7267\u517b\u4e0e\u4f20\u9053\u4e8b\u5de5\u3002',es:'Originario de Shenyang, China, el pastor Moses Fang respondi\xf3 al llamado de Dios al ministerio a los diecis\xe9is a\xf1os. Comenz\xf3 a servir en zonas rurales de China, donde fund\xf3 iglesias, dirigi\xf3 estudios b\xedblicos, predic\xf3 y ejerci\xf3 el ministerio pastoral. A lo largo de los a\xf1os, sirvi\xf3 como ministro en varias regiones.\n\nTras llegar a Estados Unidos, fue pastor de la Iglesia Adventista del S\xe9ptimo D\xeda China de Boston. M\xe1s tarde se gradu\xf3 de la Universidad Andrews con una Maestr\xeda en Divinidad (MDiv). Desde 2022 es el pastor de la Iglesia Adventista del S\xe9ptimo D\xeda China de Nueva York, donde contin\xfaa su ministerio de cuidado pastoral y evangelismo.'}},{name:{en:'Sarah Hao',zh:'\u90dd\u96c5\u541b','zh-cn':'\u90dd\u96c5\u541b',es:'Sarah Hao'},roleKey:'bibleWorker',roleNote:{en:'Elder at her home church',zh:'\u6bcd\u6703\u9577\u8001','zh-cn':'\u6bcd\u4f1a\u957f\u8001',es:'Anciana en su iglesia de origen'},imageUrl:n.BIBLE_WORKER_IMAGE_URL,description:{en:'Originally from Shenyang, China, Sarah Hao began her ministry in evangelism and church planting forty years ago. She has devoted much of her life to planting and nurturing churches in rural areas of Northeast China and has been directly or indirectly involved in establishing more than twenty churches.\n\nShe has extensive experience in training lay leaders and church workers and is particularly gifted in leading spiritual formation, Bible study, and discipleship. She is currently pursuing a Master of Divinity (MDiv) degree at the Adventist International Institute of Advanced Studies (AIIAS) in the Philippines.',zh:'\u4f86\u81ea\u4e2d\u570b\u700b\u967d\uff0c\u56db\u5341\u5e74\u524d\u958b\u59cb\u6295\u8eab\u50b3\u9053\u8207\u690d\u5802\u4e8b\u5de5\uff0c\u9577\u671f\u5728\u4e2d\u570b\u6771\u5317\u8fb2\u6751\u5730\u5340\u5efa\u7acb\u548c\u7267\u990a\u6559\u6703\u3002\u4e00\u751f\u4e2d\u76f4\u63a5\u6216\u9593\u63a5\u53c3\u8207\u5efa\u7acb\u6559\u6703\u4e8c\u5341\u9918\u9593\uff0c\u4e26\u9577\u671f\u81f4\u529b\u65bc\u57f9\u990a\u5e73\u4fe1\u5f92\u50b3\u9053\u4eba\u53ca\u6559\u6703\u5de5\u4eba\uff0c\u64c5\u9577\u5e36\u9818\u9748\u4fee\u3001\u8056\u7d93\u5b78\u7fd2\u53ca\u9580\u5f92\u57f9\u8a13\u3002\u73fe\u65bc\u83f2\u5f8b\u8cd3\u5fa9\u81e8\u570b\u969b\u9ad8\u7b49\u7814\u7a76\u9662\uff08Adventist International Institute of Advanced Studies, AIIAS\uff09\u653b\u8b80\u9053\u5b78\u78a9\u58eb\uff08Master of Divinity, MDiv\uff09\u5b78\u4f4d\u3002','zh-cn':'\u6765\u81ea\u4e2d\u56fd\u6c88\u9633\uff0c\u56db\u5341\u5e74\u524d\u5f00\u59cb\u6295\u8eab\u4f20\u9053\u4e0e\u690d\u5802\u4e8b\u5de5\uff0c\u957f\u671f\u5728\u4e2d\u56fd\u4e1c\u5317\u519c\u6751\u5730\u533a\u5efa\u7acb\u548c\u7267\u517b\u6559\u4f1a\u3002\u4e00\u751f\u4e2d\u76f4\u63a5\u6216\u95f4\u63a5\u53c2\u4e0e\u5efa\u7acb\u6559\u4f1a\u4e8c\u5341\u4f59\u95f4\uff0c\u5e76\u957f\u671f\u81f4\u529b\u4e8e\u57f9\u517b\u5e73\u4fe1\u5f92\u4f20\u9053\u4eba\u53ca\u6559\u4f1a\u5de5\u4eba\uff0c\u64c5\u957f\u5e26\u9886\u7075\u4fee\u3001\u5723\u7ecf\u5b66\u4e60\u53ca\u95e8\u5f92\u57f9\u8bad\u3002\u73b0\u4e8e\u83f2\u5f8b\u5bbe\u590d\u4e34\u56fd\u9645\u9ad8\u7b49\u7814\u7a76\u9662\uff08Adventist International Institute of Advanced Studies, AIIAS\uff09\u653b\u8bfb\u9053\u5b66\u7855\u58eb\uff08Master of Divinity, MDiv\uff09\u5b66\u4f4d\u3002',es:'Originaria de Shenyang, China, Sarah Hao comenz\xf3 su ministerio de evangelismo y fundaci\xf3n de iglesias hace cuarenta a\xf1os. Ha dedicado gran parte de su vida a fundar y nutrir iglesias en zonas rurales del noreste de China, y ha participado directa o indirectamente en el establecimiento de m\xe1s de veinte iglesias.\n\nTiene amplia experiencia en la formaci\xf3n de l\xedderes laicos y obreros de iglesia, y tiene un don especial para guiar la formaci\xf3n espiritual, el estudio de la Biblia y el discipulado. Actualmente cursa una Maestr\xeda en Divinidad (MDiv) en el Instituto Internacional Adventista de Estudios Avanzados (AIIAS), en Filipinas.'}}]},2415,[1424]);